cause.patch:
diff --git a/nginx.conf b/nginx.conf
@@ -29,6 +29,15 @@ server {
     # Must always show the running build; 404 instead of the app when it is missing.
     location = /version.json { expires -1; try_files $uri =404; }

+    # Same routes as proxy.conf.json, so the image also runs next to the backend's local
+    # compose stack (web-prod) without Caddy. In production Caddy answers these paths first.
+    location /api/ {
+        proxy_pass http://web-prod:8000;
+        proxy_set_header Host $host;
+        proxy_set_header X-Forwarded-Proto $scheme;
+        client_max_body_size 55m;
+    }
+
     # Single-page app: unknown paths fall back to index.html.
     location / { try_files $uri $uri/ /index.html; }
 }
